package com.alsafa.native4.core;

import android.content.ContentValues;import android.database.Cursor;import android.database.sqlite.SQLiteDatabase;import com.alsafa.native4.sync.SyncOperation;import org.json.JSONArray;import org.json.JSONObject;import java.util.ArrayList;import java.util.List;import java.util.UUID;
/** Customer sale: partial payment remains due; explicit final price edit is an audited discount/increase. */
public final class AdvancedSaleStore {
 private final CoreStore.DbProvider provider;private final String deviceId;public AdvancedSaleStore(CoreStore.DbProvider provider,String deviceId){this.provider=provider;this.deviceId=deviceId;}
 public Result sale(String productId,int qty,String customerId,double discount,String currency,String payment,int pointsUsed)throws Exception{String cur=MoneyRules.currency(currency),pay=payment(payment);List<SplitPaymentStore.Payment> ps=new ArrayList<>();if(!"LATER".equals(pay))ps.add(new SplitPaymentStore.Payment(-1,cur,pay,drawer(pay)));return saleSplit(productId,qty,customerId,discount,cur,ps,pointsUsed,"LATER".equals(pay));}
 public Result saleSplit(String productId,int qty,String customerId,double discount,String invoiceCurrency,List<SplitPaymentStore.Payment> payments,int pointsUsed,boolean allowBalanceDue)throws Exception{return saleSplitAdjusted(productId,qty,customerId,discount,invoiceCurrency,payments,pointsUsed,allowBalanceDue,null,false,"");}
 /** finalAmount is null for normal sale. A different finalAmount requires confirmation and is recorded as discount/increase. */
 public Result saleSplitAdjusted(String productId,int qty,String customerId,double discount,String invoiceCurrency,List<SplitPaymentStore.Payment> payments,int pointsUsed,boolean allowBalanceDue,Double finalAmount,boolean confirmed,String reason)throws Exception{if(qty<=0)throw new IllegalArgumentException("الكمية غير صالحة");if(discount<0||!Double.isFinite(discount))throw new IllegalArgumentException("الخصم غير صالح");SQLiteDatabase db=provider.db();db.beginTransaction();try{String name;int before;double price,cost;try(Cursor c=db.rawQuery("SELECT name,quantity,sale_price,cost_price FROM products WHERE product_id=? AND deleted_at IS NULL",new String[]{productId})){if(!c.moveToFirst())throw new IllegalArgumentException("المنتج غير موجود");name=c.getString(0);before=c.getInt(1);price=c.getDouble(2);cost=c.getDouble(3);}if(before<qty)throw new IllegalArgumentException("المخزون غير كافٍ");int points=0;if(!trim(customerId).isEmpty()){try(Cursor c=db.rawQuery("SELECT loyalty_points FROM customers WHERE customer_id=? AND deleted_at IS NULL",new String[]{customerId})){if(!c.moveToFirst())throw new IllegalArgumentException("العميل غير موجود");points=c.getInt(0);}}if(pointsUsed<0||pointsUsed>points)throw new IllegalArgumentException("نقاط العميل غير كافية");double subtotal=price*qty,agreed=Math.max(0,subtotal-discount);if(finalAmount!=null&&(!Double.isFinite(finalAmount)||finalAmount<0))throw new IllegalArgumentException("القيمة النهائية غير صالحة");double total=finalAmount==null?agreed:finalAmount,capital=cost*qty,profit=total-capital;long now=System.currentTimeMillis();String iid="sale-"+UUID.randomUUID(),no="S-"+now,cur=MoneyRules.currency(invoiceCurrency);SettlementAdjustmentStore.Result adj=null;if(Math.abs(total-agreed)>0.000001)adj=SettlementAdjustmentStore.requireAndWrite(db,"SALE",iid,agreed,total,cur,confirmed,reason,now);double customerDiscount=adj==null?0:adj.discount;String adjustmentKind=adj==null?"NONE":adj.kind;ContentValues inv=new ContentValues();inv.put("invoice_id",iid);inv.put("invoice_no",no);inv.put("invoice_type","SALE");inv.put("currency",cur);inv.put("subtotal",subtotal);inv.put("discount",discount+customerDiscount);inv.put("total",total);inv.put("payment_method","SPLIT");inv.put("created_at",now);inv.put("updated_at",now);db.insertOrThrow("invoices",null,inv);ContentValues it=new ContentValues();it.put("item_id","item-"+UUID.randomUUID());it.put("invoice_id",iid);it.put("product_id",productId);it.put("description",name);it.put("quantity",qty);it.put("unit_price",price);it.put("total",subtotal);it.put("unit_cost_snapshot",cost);it.put("cost_total_snapshot",capital);it.put("profit_snapshot",profit);it.put("created_at",now);db.insertOrThrow("invoice_items",null,it);FxSnapshotStore.Snapshot invoiceFx=FxSnapshotStore.capture(db,"SALE",iid,cur,total,now);List<SplitPaymentStore.Payment> normalized=normalizeLegacy(payments,total);double paidUsd=0;for(SplitPaymentStore.Payment p:normalized)paidUsd+=usd(db,p.currency,p.amount,now);double dueUsd=invoiceFx.usdAmount-paidUsd;if(dueUsd < -0.01)throw new IllegalArgumentException("مجموع الدفعات أكبر من قيمة الفاتورة");if(!allowBalanceDue&&dueUsd>0.01)throw new IllegalArgumentException("مجموع الدفعات أقل من قيمة الفاتورة");JSONArray paymentJson=normalized.isEmpty()?new JSONArray():SplitPaymentStore.write(db,"SALE",iid,normalized,now);int after=before-qty;ContentValues pv=new ContentValues();pv.put("quantity",after);pv.put("updated_at",now);db.update("products",pv,"product_id=?",new String[]{productId});ContentValues sm=new ContentValues();sm.put("move_id","stock-"+UUID.randomUUID());sm.put("product_id",productId);sm.put("source_type","SALE");sm.put("source_id",iid);sm.put("before_qty",before);sm.put("delta_qty",-qty);sm.put("after_qty",after);sm.put("created_at",now);db.insertOrThrow("stock_moves",null,sm);if(pointsUsed>0){ContentValues cv=new ContentValues();cv.put("loyalty_points",points-pointsUsed);cv.put("updated_at",now);db.update("customers",cv,"customer_id=?",new String[]{customerId});}JSONObject j=new JSONObject().put("invoiceId",iid).put("invoiceNo",no).put("productId",productId).put("quantity",qty).put("subtotal",subtotal).put("baseDiscount",discount).put("agreedAmount",agreed).put("finalAmount",total).put("customerDiscount",customerDiscount).put("adjustmentKind",adjustmentKind).put("invoiceCurrency",cur).put("payments",paymentJson).put("balanceDueUsd",Math.max(0,dueUsd)).put("customerId",trim(customerId)).put("pointsUsed",pointsUsed).put("capitalSnapshot",capital).put("profitSnapshot",profit).put("invoiceUsdSnapshot",invoiceFx.usdAmount).put("updatedAt",now);provider.enqueue(db,SyncOperation.create(SyncOperation.Kind.SALE,iid,j.toString(),deviceId));db.setTransactionSuccessful();return new Result(iid,no,agreed,total,customerDiscount,capital,profit,invoiceFx.usdAmount,Math.max(0,dueUsd),adjustmentKind,after);}finally{db.endTransaction();}}
 private static List<SplitPaymentStore.Payment> normalizeLegacy(List<SplitPaymentStore.Payment> src,double total){List<SplitPaymentStore.Payment> out=new ArrayList<>();if(src==null)return out;for(SplitPaymentStore.Payment p:src){if(p==null)continue;out.add(p.amount<0?new SplitPaymentStore.Payment(total,p.currency,p.paymentMethod,p.account):p);}return out;}
 private static double usd(SQLiteDatabase db,String currency,double amount,long now){return FxSnapshotStore.capture(db,"PAYMENT_CHECK","check-"+UUID.randomUUID(),MoneyRules.currency(currency),amount,now).usdAmount;}
 public static final class Result{public final String invoiceId,invoiceNo,adjustmentKind;public final double agreedTotal,total,customerDiscount,capital,profit,totalUsd,balanceDueUsd;public final int remainingQty;Result(String id,String n,double a,double t,double disc,double c,double p,double u,double d,String k,int q){invoiceId=id;invoiceNo=n;agreedTotal=a;total=t;customerDiscount=disc;capital=c;profit=p;totalUsd=u;balanceDueUsd=d;adjustmentKind=k;remainingQty=q;}}
 private static String drawer(String p){if(p.equals("SHAM_CASH"))return "SHAM_CASH";if(p.equals("BANK"))return "BANK";if(p.equals("EXTERNAL"))return "EXTERNAL";return "MAIN";}private static String payment(String v){String x=trim(v).toUpperCase();return x.equals("SHAM_CASH")||x.equals("BANK")||x.equals("EXTERNAL")||x.equals("LATER")?x:"CASH";}private static String trim(String v){return v==null?"":v.trim();}
}
